-- Real prices, sizes and descriptions, from Beco.
--
-- Two sources, both supplied by Irene on 1 September 2026:
--   * "Beco Product Data (fill in what you know)", the sheet sent in week 1,
--     returned with a price and a slab size for all 24 stones.
--   * "12MM Sintered Stone Descriptions.docx", carrying prose, finish, body
--     composition and face type for 22 of them.
--
-- This is the change that turns a gallery into a catalogue. A9 assumed
-- everything would launch POA because no price data existed anywhere; it now
-- does, so the stones move to fixed pricing and in stock.
--
-- The importer no longer touches these columns, per the fix that stopped it
-- rewriting commercial fields on every run, so a nightly Drive sync cannot
-- undo any of it.

create temporary table product_data (
  slug        text primary key,
  price       numeric(12,2),
  description text,
  short_desc  text,
  specs       jsonb,
  face        text
) on commit preserve rows;

