;

update products p set
  price               = d.price,
  price_display_mode  = 'fixed',
  availability        = 'in_stock',
  unit                = 'per slab',
  description         = coalesce(d.description, p.description),
  short_description   = coalesce(d.short_desc, p.short_description),
  specs               = d.specs,
  -- The descriptions document states the face type explicitly, which is a
  -- better source than the presence of a BOOK MATCH photograph.
  face_type           = coalesce(d.face::face_type, p.face_type)
from product_data d
where p.slug = d.slug;

drop table product_data;
